import{_ as u,a0 as a,w as o,s as l,I as e,x as i,a1 as n,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何创建定制的 Ubuntu Live CD 镜像 | LCTT x X-CMD","titleTemplate":false,"description":"如何创建定制的 Ubuntu Live CD 镜像 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何创建定制的 Ubuntu Live CD 镜像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何创建定制的 Ubuntu Live CD 镜像 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171030 How To Create Custom Ubuntu Live CD Image","title":"如何创建定制的 Ubuntu Live CD 镜像","tag":"201801","desc":""},"relativePath":"201801/20171030 How To Create Custom Ubuntu Live CD Image.md","filePath":"[post].md"}'),d={name:"201801/20171030 How To Create Custom Ubuntu Live CD Image.md"};function c(b,t,g,h,C,k){const s=a("Link");return o(),l("div",null,[t[24]||(t[24]=e("h1",{id:"如何创建定制的-ubuntu-live-cd-镜像",tabindex:"-1"},[i("如何创建定制的 Ubuntu Live CD 镜像 "),e("a",{class:"header-anchor",href:"#如何创建定制的-ubuntu-live-cd-镜像","aria-label":"Permalink to “如何创建定制的 Ubuntu Live CD 镜像”"},"​")],-1)),t[25]||(t[25]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-720x340.png",alt:""})],-1)),e("p",null,[t[1]||(t[1]=i("今天让我们来讨论一下如何创建 Ubuntu Live CD 的定制镜像（ISO）。我们以前可以使用 ",-1)),n(s,{href:"https://www.ostechnix.com/pinguy-builder-build-custom-ubuntu-os/"},{default:p(()=>[...t[0]||(t[0]=[i("Pinguy Builder",-1)])]),_:1}),t[2]||(t[2]=i(" 完成这项工作。但是，现在它似乎停止维护了。最近 Pinguy Builder 的官方网站似乎没有任何更新。幸运的是，我找到了另一种创建 Ubuntu Live CD 镜像的工具。使用 Cubic 即 ",-1)),t[3]||(t[3]=e("strong",null,"C",-1)),t[4]||(t[4]=i("ustom ",-1)),t[5]||(t[5]=e("strong",null,"Ub",-1)),t[6]||(t[6]=i("untu ",-1)),t[7]||(t[7]=e("strong",null,"I",-1)),t[8]||(t[8]=i("SO ",-1)),t[9]||(t[9]=e("strong",null,"C",-1)),t[10]||(t[10]=i("reator 的首字母缩写，这是一个用来创建定制的可启动的 Ubuntu Live CD（ISO）镜像的 GUI 应用程序。",-1))]),t[26]||(t[26]=r(`<p>Cubic 正在积极开发，它提供了许多选项来轻松地创建一个定制的 Ubuntu Live CD ，它有一个集成的 chroot 命令行环境（LCTT 译注：chroot —— Change Root，也就是改变程序执行时所参考的根目录位置），在那里你可以定制各种方面，比如安装新的软件包、内核，添加更多的背景壁纸，添加更多的文件和文件夹。它有一个直观的 GUI 界面，在 live 镜像创建过程中可以轻松的利用导航（可以利用点击鼠标来回切换）。您可以创建一个新的自定义镜像或修改现有的项目。因为它可以用来制作 Ubuntu live 镜像，所以我相信它可以用在制作其他 Ubuntu 的发行版和衍生版镜像中，比如 Linux Mint。</p><h3 id="安装-cubic" tabindex="-1">安装 Cubic <a class="header-anchor" href="#安装-cubic" aria-label="Permalink to “安装 Cubic”">​</a></h3><p>Cubic 的开发人员已经做出了一个 PPA 来简化安装过程。要在 Ubuntu 系统上安装 Cubic ，在你的终端上运行以下命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:cubic-wizard/release</span></span>
<span class="line"><span>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 6494C6D6997C215E</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install cubic</span></span></code></pre></div><h3 id="利用-cubic-创建-ubuntu-live-cd-的定制镜像" tabindex="-1">利用 Cubic 创建 Ubuntu Live CD 的定制镜像 <a class="header-anchor" href="#利用-cubic-创建-ubuntu-live-cd-的定制镜像" aria-label="Permalink to “利用 Cubic 创建 Ubuntu Live CD 的定制镜像”">​</a></h3><p>安装完成后，从应用程序菜单或 dock 启动 Cubic。这是在我在 Ubuntu 16.04 LTS 桌面系统中 Cubic 的样子。</p><p>为新项目选择一个目录。它是保存镜像文件的目录。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-1.png" alt=""></p><p>请注意，Cubic 不是创建您当前系统的 Live CD 镜像，而是利用 Ubuntu 的安装 CD 来创建一个定制的 Live CD，因此，你应该有一个最新的 ISO 镜像。</p><p>选择您存储 Ubuntu 安装 ISO 镜像的路径。Cubic 将自动填写您定制操作系统的所有细节。如果你愿意，你可以改变细节。单击 Next 继续。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-2.png" alt=""></p><p>接下来，来自源安装介质中的压缩的 Linux 文件系统将被提取到项目的目录（在我们的例子中目录的位置是 <code>/home/ostechnix/custom_ubuntu</code>)。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-3.png" alt=""></p><p>一旦文件系统被提取出来，将自动加载到 chroot 环境。如果你没有看到终端提示符，请按几次回车键。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-4.png" alt=""></p><p>在这里可以安装任何额外的软件包，添加背景图片，添加软件源列表，添加最新的 Linux 内核和所有其他定制到你的 Live CD 。</p><p>例如，我希望 <code>vim</code> 安装在我的 Live CD 中，所以现在就要安装它。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-6.png" alt=""></p><p>我们不需要使用 <code>sudo</code>，因为我们已经在具有最高权限（root）的环境中了。</p><p>类似地，如果需要，可以安装更多的任何版本 Linux 内核。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt install linux-image-extra-4.10.0-24-generic</span></span></code></pre></div><p>此外，您还可以更新软件源列表（添加或删除软件存储库列表）：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-5.png" alt=""></p><p>修改源列表后，不要忘记运行 <code>apt update</code> 命令来更新源列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt update</span></span></code></pre></div><p>另外，您还可以向 Live CD 中添加文件或文件夹。复制文件或文件夹（右击它们并选择复制或者利用 <code>CTRL+C</code>），在终端右键单击（在 Cubic 窗口内)，选择 “Paste file(s)”，最后点击 Cubic 向导底部的 “Copy”。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-7.png" alt=""></p><p><strong>Ubuntu 17.10 用户注意事项</strong></p><blockquote><p>在 Ubuntu 17.10 系统中，DNS 查询可能无法在 chroot 环境中工作。如果您正在制作一个定制的 Ubuntu 17.10 Live 镜像，您需要指向正确的 <code>resolve.conf</code> 配置文件：</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -sr /run/systemd/resolve/resolv.conf /run/systemd/resolve/stub-resolv.conf</span></span></code></pre></div><p>要验证 DNS 解析工作，运行:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/resolv.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google.com</span></span></code></pre></div><p>如果你想的话，可以添加你自己的壁纸。要做到这一点，请切换到 <code>/usr/share/backgrounds/</code> 目录，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /usr/share/backgrounds</span></span></code></pre></div><p>并将图像拖放到 Cubic 窗口中。或复制图像，右键单击 Cubic 终端窗口并选择 “Paste file(s)” 选项。此外，确保你在 <code>/usr/share/gnome-backproperties</code> 的XML文件中添加了新的壁纸，这样你可以在桌面上右键单击新添加的图像选择 “Change Desktop Background” 进行交互。完成所有更改后，在 Cubic 向导中单击 “Next”。</p><p>接下来，选择引导到新的 Live ISO 镜像时使用的 Linux 内核版本。如果已经安装了其他版本内核，它们也将在这部分中被列出。然后选择您想在 Live CD 中使用的内核。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-8.png" alt=""></p><p>在下一节中，选择要从您的 Live 映像中删除的软件包。在使用定制的 Live 映像安装完 Ubuntu 操作系统后，所选的软件包将自动删除。在选择要删除的软件包时，要格外小心，您可能在不知不觉中删除了一个软件包，而此软件包又是另外一个软件包的依赖包。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-10-1.png" alt=""></p><p>接下来， Live 镜像创建过程将开始。这里所要花费的时间取决于你定制的系统规格。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-12-1.png" alt=""></p><p>镜像创建完成后后，单击 “Finish”。Cubic 将显示新创建的自定义镜像的细节。</p><p>如果你想在将来修改刚刚创建的自定义 Live 镜像，不要选择“ Delete all project files, except the generated disk image and the corresponding MD5 checksum file”（除了生成的磁盘映像和相应的 MD5 校验和文件之外，删除所有的项目文件**） ，Cubic 将在项目的工作目录中保留自定义图像，您可以在将来进行任何更改。而不用从头再来一遍。</p><p>要为不同的 Ubuntu 版本创建新的 Live 镜像，最好使用不同的项目目录。</p><h3 id="利用-cubic-修改-ubuntu-live-cd-的定制镜像" tabindex="-1">利用 Cubic 修改 Ubuntu Live CD 的定制镜像 <a class="header-anchor" href="#利用-cubic-修改-ubuntu-live-cd-的定制镜像" aria-label="Permalink to “利用 Cubic 修改 Ubuntu Live CD 的定制镜像”">​</a></h3><p>从菜单中启动 Cubic ，并选择一个现有的项目目录。单击 “Next” 按钮，您将看到以下三个选项：</p><ol><li>Create a disk image from the existing project. （从现有项目创建一个磁盘映像。）</li><li>Continue customizing the existing project.（继续定制现有项目。）</li><li>Delete the existing project.（删除当前项目。）</li></ol><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-13.png" alt=""></p><p>第一个选项将允许您从现有项目中使用之前所做的自定义设置创建一个新的 Live ISO 镜像。如果您丢失了 ISO 镜像，您可以使用第一个选项来创建一个新的。</p><p>第二个选项允许您在现有项目中进行任何其他更改。如果您选择此选项，您将再次进入 chroot 环境。您可以添加新的文件或文件夹，安装任何新的软件，删除任何软件，添加其他的 Linux 内核，添加桌面背景等等。</p><p>第三个选项将删除现有的项目，所以您可以从头开始。选择此选项将删除所有文件，包括新生成的 ISO 镜像文件。</p><p>我用 Cubic 做了一个定制的 Ubuntu 16.04 LTS 桌面 Live CD 。就像这篇文章里描述的一样。如果你想创建一个 Ubuntu Live CD， Cubic 可能是一个不错的选择。</p><p>就这些了，再会！</p><hr>`,54)),e("p",null,[t[12]||(t[12]=i("via: ",-1)),n(s,{href:"https://www.ostechnix.com/create-custom-ubuntu-live-cd-image/"},{default:p(()=>[...t[11]||(t[11]=[i("https://www.ostechnix.com/create-custom-ubuntu-live-cd-image/",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=i("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>[...t[13]||(t[13]=[i("SK",-1)])]),_:1}),t[17]||(t[17]=i(" 译者：",-1)),n(s,{href:"https://github.com/stevenzdg988"},{default:p(()=>[...t[14]||(t[14]=[i("stevenzdg988",-1)])]),_:1}),t[18]||(t[18]=i(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[15]||(t[15]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=i("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:p(()=>[...t[20]||(t[20]=[i("Linux中国",-1)])]),_:1}),t[23]||(t[23]=i(" 荣誉推出",-1))])])}const x=u(d,[["render",c]]);export{w as __pageData,x as default};
